add("it5.q1", ("विद्युत परिपथों तथा साधित्रों में सामान्यतः उपयोग होने वाले दो सुरक्षा उपायों के नाम लिखिए।", "વિદ્યુત-પરિપથો અને ઉપકરણોમાં સામાન્ય રીતે વપરાતા બે સલામતી ઉપાયોનાં નામ લખો."),
    {0: ("विद्युन्मय तार के श्रेणीक्रम में विद्युत फ़्यूज़ (या लघु परिपथ विच्छेदक)।", "જીવંત તાર સાથે શ્રેણીમાં વિદ્યુત-ફ્યૂઝ (કે મિનિએચર સર્કિટ બ્રેકર)."), 1: ("भूसंपर्कण: उपकरण के धात्विक आवरण को भूमि से जोड़ने वाला भूसंपर्क तार।", "અર્થિંગ: ઉપકરણના ધાતુના આવરણને જમીન સાથે જોડતો અર્થિંગ તાર.")})
add("it5.q2", ("2 kW शक्ति अनुमतांक का एक विद्युत तंदूर किसी घरेलू विद्युत परिपथ (220 V) में प्रचालित किया जाता है जिसका विद्युत धारा अनुमतांक 5 A है, इससे आप किस परिणाम की अपेक्षा करते हैं? स्पष्ट कीजिए।", "2 kW પાવર-રેટિંગનું વિદ્યુત-ઓવન ઘરેલુ પરિપથ (220 V) માં ચલાવાય છે, જેનું પ્રવાહ-રેટિંગ 5 A છે. તમે કયા પરિણામની અપેક્ષા રાખો છો? સમજાવો."),
    {1: ("यह 5 A अनुमतांक से अधिक है, इसलिए परिपथ अतिभारित होगा और फ़्यूज़ उड़ जाएगा (पिघल जाएगा), जिससे आपूर्ति कट जाएगी।", "તે 5 A રેટિંગ કરતાં વધુ છે, તેથી પરિપથ ઓવરલોડ થશે અને ફ્યૂઝ ઊડી જશે (પીગળી જશે), જેથી પુરવઠો કપાઈ જશે.")})
add("it5.q3", ("घरेलू विद्युत परिपथों में अतिभारण से बचाव के लिए क्या सावधानी बरतनी चाहिए?", "ઘરેલુ વિદ્યુત-પરિપથમાં ઓવરલોડિંગથી બચવા કઈ સાવચેતી રાખવી જોઈએ?"),
    {0: ("एक ही सॉकेट से एक साथ बहुत से उपकरण न जोड़ें।", "એક જ સૉકેટ સાથે એકસાથે ઘણાં ઉપકરણો ન જોડો."), 1: ("परिपथ के अनुमतांक के भीतर धारा लेने वाले उपकरण चलाएँ (भारी उपकरण 15 A के परिपथ पर), और सही अनुमतांक का फ़्यूज़ या MCB लगाएँ।", "પરિપથના રેટિંગની અંદર પ્રવાહ લેતાં ઉપકરણો ચલાવો (ભારે ઉપકરણો 15 A ના પરિપથ પર), અને યોગ્ય રેટિંગનો ફ્યૂઝ કે MCB વાપરો.")})

