mc("ex.q1", ("निम्नलिखित में से कौन किसी लंबे विद्युत धारावाही तार के निकट चुंबकीय क्षेत्र का सही वर्णन करता है?", "નીચેનામાંથી કયું લાંબા પ્રવાહધારિત તારની નજીક ચુંબકીય ક્ષેત્રનું સાચું વર્ણન કરે છે?"), ("क्षेत्र रेखाएँ तार के चारों ओर संकेंद्री वृत्त हैं।", "ક્ષેત્રરેખાઓ તારની આસપાસ સમકેન્દ્રી વર્તુળો છે."),
   {EX1[0]: (("क्षेत्र की क्षेत्र रेखाएँ तार के लंबवत सरल रेखाएँ हैं।", "ક્ષેત્રની રેખાઓ તારને લંબ સુરેખાઓ છે."), ("रेखाएँ तार के चारों ओर घूमती हैं।", "રેખાઓ તારની આસપાસ ફરે છે.")),
    EX1[1]: (("क्षेत्र की क्षेत्र रेखाएँ तार के समांतर सरल रेखाएँ हैं।", "ક્ષેત્રની રેખાઓ તારને સમાંતર સુરેખાઓ છે."), ("रेखाएँ तार के चारों ओर घूमती हैं।", "રેખાઓ તારની આસપાસ ફરે છે.")),
    EX1[2]: (("क्षेत्र की क्षेत्र रेखाएँ तार से निकलती अरीय रेखाएँ हैं।", "ક્ષેત્રની રેખાઓ તારમાંથી નીકળતી ત્રિજ્યાવર્તી રેખાઓ છે."), ("रेखाएँ वृत्त हैं, अरीय नहीं।", "રેખાઓ વર્તુળો છે, ત્રિજ્યાવર્તી નહિ.")),
    EX1[3]: (("क्षेत्र की क्षेत्र रेखाएँ तार पर केंद्रित संकेंद्री वृत्त हैं।", "ક્ષેત્રની રેખાઓ તાર પર કેન્દ્રિત સમકેન્દ્રી વર્તુળો છે."), OK)})
mc("ex.q2", ("लघुपथन के समय परिपथ में विद्युत धारा का मान", "શૉર્ટ સર્કિટ વખતે પરિપથમાં પ્રવાહ"), ("प्रतिरोध लगभग शून्य हो जाता है, इसलिए धारा बहुत अधिक हो जाती है।", "અવરોધ લગભગ શૂન્ય થાય છે, તેથી પ્રવાહ ખૂબ વધી જાય છે."),
   {"reduces substantially.": (("बहुत कम हो जाता है।", "ખૂબ ઘટી જાય છે."), ("प्रतिरोध घटता है, इसलिए धारा बढ़ती है।", "અવરોધ ઘટે છે, તેથી પ્રવાહ વધે છે.")), "does not change.": (("परिवर्तित नहीं होता।", "બદલાતો નથી."), ("यह तेज़ी से बढ़ता है।", "તે ઝડપથી વધે છે.")),
    "increases heavily.": (("बहुत अधिक बढ़ जाता है।", "ખૂબ વધી જાય છે."), OK), "vary continuously.": (("निरंतर परिवर्तित होता है।", "સતત બદલાતો રહે છે."), ("यह तेज़ी से बढ़ता है।", "તે ઝડપથી વધે છે."))})
tf("ex.q3a", ("विद्युत धारावाही लंबी वृत्ताकार कुंडली के केंद्र पर चुंबकीय क्षेत्र समांतर सीधी क्षेत्र रेखाएँ होता है।", "પ્રવાહધારિત લાંબા વર્તુળાકાર ગૂંચળાના કેન્દ્રે ચુંબકીય ક્ષેત્ર સમાંતર સીધી રેખાઓ હોય છે."),
   ("धारावाही वृत्ताकार कुंडली के केंद्र के पास क्षेत्र रेखाएँ सीधी और समांतर होती हैं।", "પ્રવાહધારિત વર્તુળાકાર ગૂંચળાના કેન્દ્ર પાસે ક્ષેત્રરેખાઓ સીધી અને સમાંતર હોય છે."))
tf("ex.q3b", ("हरे विद्युतरोधी आवरण का तार प्रायः विद्युन्मय तार होता है।", "લીલા અવાહક આવરણવાળો તાર સામાન્ય રીતે જીવંત તાર હોય છે."),
   ("हरा तार भूसंपर्क तार है; विद्युन्मय तार का आवरण लाल होता है।", "લીલો તાર અર્થિંગ તાર છે; જીવંત તારનું આવરણ લાલ હોય છે."))
add("ex.q4", ("चुंबकीय क्षेत्र उत्पन्न करने के दो तरीकों की सूची बनाइए।", "ચુંબકીય ક્ષેત્ર ઉત્પન્ન કરવાની બે રીતોની યાદી બનાવો."),
    {0: ("स्थायी चुंबक, जैसे छड़ चुंबक, का उपयोग करके।", "કાયમી ચુંબક, જેમ કે ગજિયું ચુંબક, વાપરીને."), 1: ("किसी चालक में विद्युत धारा प्रवाहित करके: सीधा तार, वृत्ताकार लूप या परिनालिका (विद्युत चुंबक)।", "કોઈ વાહકમાંથી વિદ્યુતપ્રવાહ પસાર કરીને: સીધો તાર, વર્તુળાકાર લૂપ કે સોલેનોઇડ (વિદ્યુતચુંબક).")})
add("ex.q5", ("चुंबकीय क्षेत्र में स्थित विद्युत धारावाही चालक पर आरोपित बल कब अधिकतम होता है?", "ચુંબકીય ક્ષેત્રમાં મૂકેલા પ્રવાહધારિત વાહક પર લાગતું બળ ક્યારે મહત્તમ હોય છે?"),
    {0: ("जब धारा की दिशा चुंबकीय क्षेत्र के लंबवत हो।", "જ્યારે પ્રવાહની દિશા ચુંબકીય ક્ષેત્રને લંબ હોય."), 1: ("(जब धारा क्षेत्र के समांतर हो, तब बल शून्य होता है।)", "(જ્યારે પ્રવાહ ક્ષેત્રને સમાંતર હોય, ત્યારે બળ શૂન્ય હોય છે.)")})
add("ex.q6", ("मान लीजिए आप किसी चैंबर में अपनी पीठ को किसी एक दीवार से लगाकर बैठे हैं। कोई इलेक्ट्रॉन-पुंज आपके पीछे की दीवार से सामने वाली दीवार की ओर क्षैतिजतः गमन करते हुए किसी प्रबल चुंबकीय क्षेत्र द्वारा आपके दाईं ओर विक्षेपित हो जाता है। चुंबकीय क्षेत्र की दिशा क्या है?",
              "ધારો કે તમે કોઈ ઓરડામાં એક દીવાલ તરફ પીઠ રાખીને બેઠા છો. એક ઇલેક્ટ્રૉન-પુંજ પાછળની દીવાલથી સામેની દીવાલ તરફ સમક્ષિતિજ ગતિ કરતાં પ્રબળ ચુંબકીય ક્ષેત્ર વડે તમારી જમણી બાજુ વિચલિત થાય છે. ચુંબકીય ક્ષેત્રની દિશા શી છે?"),
    {0: ("इलेक्ट्रॉन सामने की दीवार की ओर जाते हैं, इसलिए धारा पीछे की दीवार की ओर है; बल दाईं ओर है।", "ઇલેક્ટ્રૉન સામેની દીવાલ તરફ જાય છે, તેથી પ્રવાહ પાછળની દીવાલ તરફ છે; બળ જમણી બાજુ છે."), 1: ("फ़्लेमिंग के वामहस्त नियम से चुंबकीय क्षेत्र ऊर्ध्वाधरतः नीचे की ओर है।", "ફ્લેમિંગના ડાબા હાથના નિયમથી ચુંબકીય ક્ષેત્ર ઊર્ધ્વ નીચે તરફ છે.")})
add("ex.q7", ("उस नियम को लिखिए जो (i) किसी विद्युत धारावाही सीधे चालक के चारों ओर उत्पन्न चुंबकीय क्षेत्र, (ii) किसी चुंबकीय क्षेत्र में, क्षेत्र के लंबवत स्थित, विद्युत धारावाही सीधे चालक पर आरोपित बल, तथा (iii) किसी चुंबकीय क्षेत्र में किसी कुंडली के घूर्णन करने पर उस कुंडली में उत्पन्न प्रेरित विद्युत धारा की दिशा निर्धारित करता है।",
              "એ નિયમ લખો જે (i) પ્રવાહધારિત સીધા વાહકની આસપાસ ઉત્પન્ન ચુંબકીય ક્ષેત્ર, (ii) ચુંબકીય ક્ષેત્રમાં, ક્ષેત્રને લંબ મૂકેલા પ્રવાહધારિત સીધા વાહક પર લાગતું બળ, અને (iii) ચુંબકીય ક્ષેત્રમાં ગૂંચળાના ભ્રમણથી તેમાં ઉત્પન્ન પ્રેરિત પ્રવાહની દિશા નક્કી કરે છે."),
    {0: ("(i) दक्षिण-हस्त अंगुष्ठ नियम: चालक को दाएँ हाथ में पकड़िए, अँगूठा धारा की दिशा में; मुड़ी अँगुलियाँ क्षेत्र की दिशा देती हैं।", "(i) જમણા હાથના અંગૂઠાનો નિયમ: વાહકને જમણા હાથમાં પકડો, અંગૂઠો પ્રવાહની દિશામાં; વાળેલી આંગળીઓ ક્ષેત્રની દિશા આપે છે."),
     1: ("(ii) फ़्लेमिंग का वामहस्त नियम: बाएँ हाथ का अँगूठा, तर्जनी और मध्यमा परस्पर लंबवत फैलाइए; तर्जनी = क्षेत्र, मध्यमा = धारा, अँगूठा = बल।", "(ii) ફ્લેમિંગનો ડાબા હાથનો નિયમ: ડાબા હાથનો અંગૂઠો, પ્રથમ આંગળી અને મધ્યમા પરસ્પર લંબ ફેલાવો; પ્રથમ આંગળી = ક્ષેત્ર, મધ્યમા = પ્રવાહ, અંગૂઠો = બળ."),
     2: ("(iii) फ़्लेमिंग का दक्षिण-हस्त नियम: दाएँ हाथ में तर्जनी = क्षेत्र, अँगूठा = चालक की गति, मध्यमा = प्रेरित धारा।", "(iii) ફ્લેમિંગનો જમણા હાથનો નિયમ: જમણા હાથમાં પ્રથમ આંગળી = ક્ષેત્ર, અંગૂઠો = વાહકની ગતિ, મધ્યમા = પ્રેરિત પ્રવાહ.")})
add("ex.q8", ("विद्युत लघुपथन कब होता है?", "શૉર્ટ સર્કિટ ક્યારે થાય છે?"),
    {0: ("जब विद्युन्मय तार और उदासीन तार सीधे संपर्क में आ जाते हैं, जैसे विद्युतरोधन क्षतिग्रस्त होने पर या उपकरण में दोष होने पर।", "જ્યારે જીવંત તાર અને તટસ્થ તાર સીધા સંપર્કમાં આવે, જેમ કે અવાહક આવરણ નુકસાન પામે કે ઉપકરણમાં ખામી હોય ત્યારે."), 1: ("प्रतिरोध लगभग शून्य हो जाता है, और धारा बहुत अधिक बढ़ जाती है।", "અવરોધ લગભગ શૂન્ય થાય છે, અને પ્રવાહ ખૂબ વધી જાય છે.")})
add("ex.q9", ("भूसंपर्क तार का क्या कार्य है? धातु के आवरण वाले विद्युत साधित्रों को भूसंपर्कित करना क्यों आवश्यक है?", "અર્થિંગ તારનું કાર્ય શું છે? ધાતુના આવરણવાળાં વિદ્યુત-ઉપકરણોને અર્થિંગ કરવું કેમ જરૂરી છે?"),
    {0: ("भूसंपर्क तार उपकरण के धात्विक आवरण से भूमि तक कम प्रतिरोध का पथ देता है।", "અર્થિંગ તાર ઉપકરણના ધાતુના આવરણથી જમીન સુધી ઓછા અવરોધનો માર્ગ આપે છે."), 1: ("यदि विद्युन्मय तार धात्विक आवरण को छू जाए, तो रिसने वाली धारा भूमि में चली जाती है, इसलिए उपयोगकर्ता को तीव्र झटका नहीं लगता।", "જો જીવંત તાર ધાતુના આવરણને અડી જાય, તો લીક થતો પ્રવાહ જમીનમાં ચાલ્યો જાય છે, તેથી વાપરનારને તીવ્ર આંચકો લાગતો નથી.")})

